1	import { TFile, TAbstractFile, EventRef } from "obsidian";
2	import { default as DiscourseGraphPlugin } from "~/index";
3	import {
4	  syncDiscourseNodeChanges,
5	  type ChangeType,
6	  cleanupOrphanedNodes,
7	} from "./syncDgNodesToSupabase";
8	import { getNodeTypeById } from "./typeUtils";
9	
10	type QueuedChange = {
11	  filePath: string;
12	  changeTypes: Set<ChangeType>;
13	  oldPath?: string; // For rename operations
14	};
15	
16	const DEBOUNCE_DELAY_MS = 5000; // 5 seconds
17	
18	/**
19	 * FileChangeListener monitors Obsidian vault events for DG node changes
20	 * and queues them for sync to Supabase with debouncing.
21	 */
22	export class FileChangeListener {
23	  private plugin: DiscourseGraphPlugin;
24	  private changeQueue: Map<string, QueuedChange> = new Map();
25	  private debounceTimer: NodeJS.Timeout | null = null;
26	  private eventRefs: EventRef[] = [];
27	  private metadataChangeCallback: ((file: TFile) => void) | null = null;
28	  private isProcessing = false;
29	  private hasPendingOrphanCleanup = false;
30	  private pendingCreates: Set<string> = new Set();
31	
32	  constructor(plugin: DiscourseGraphPlugin) {
33	    this.plugin = plugin;
34	  }
35	
36	  /**
37	   * Initialize the file change listener and register vault event handlers
38	   */
39	  initialize(): void {
40	    const createRef = this.plugin.app.vault.on(
41	      "create",
42	      (file: TAbstractFile) => {
43	        this.handleFileCreate(file);
44	      },
45	    );
46	    this.eventRefs.push(createRef);
47	
48	    const modifyRef = this.plugin.app.vault.on(
49	      "modify",
50	      (file: TAbstractFile) => {
51	        this.handleFileModify(file);
52	      },
53	    );
54	    this.eventRefs.push(modifyRef);
55	
56	    const deleteRef = this.plugin.app.vault.on(
57	      "delete",
58	      (file: TAbstractFile) => {
59	        this.handleFileDelete(file);
60	      },
61	    );
62	    this.eventRefs.push(deleteRef);
63	
64	    const renameRef = this.plugin.app.vault.on(
65	      "rename",
66	      (file: TAbstractFile, oldPath: string) => {
67	        this.handleFileRename(file, oldPath);
68	      },
69	    );
70	    this.eventRefs.push(renameRef);
71	
72	    this.metadataChangeCallback = (file: TFile) => {
73	      this.handleMetadataChange(file);
74	    };
75	    this.plugin.app.metadataCache.on("changed", this.metadataChangeCallback);
76	  }
77	
78	  /**
79	   * Check if a file is a DG node (has nodeTypeId in frontmatter that matches a node type in settings)
80	   */
81	  private shouldSyncFile(file: TAbstractFile): boolean {
82	    if (!(file instanceof TFile)) {
83	      return false;
84	    }
85	
86	    // Only process markdown files
87	    if (!file.path.endsWith(".md")) {
88	      return false;
89	    }
90	
91	    const cache = this.plugin.app.metadataCache.getFileCache(file);
92	    const frontmatter = cache?.frontmatter;
93	    const nodeTypeId = frontmatter?.nodeTypeId as string | undefined;
94	
95	    if (!nodeTypeId || typeof nodeTypeId !== "string") {
96	      return false;
97	    }
98	
99	    if (frontmatter?.importedFromRid) {
100	      return false;
101	    }
102	
103	    return !!getNodeTypeById(this.plugin, nodeTypeId);
104	  }
105	
106	  /**
107	   * Handle file creation event
108	   */
109	  private handleFileCreate(file: TAbstractFile): void {
110	    if (!(file instanceof TFile)) {
111	      return;
112	    }
113	
114	    if (!file.path.endsWith(".md")) {
115	      return;
116	    }
117	
118	    this.pendingCreates.add(file.path);
119	
120	    if (this.shouldSyncFile(file)) {
121	      this.queueChange(file.path, "title");
122	      this.queueChange(file.path, "content");
123	      this.pendingCreates.delete(file.path);
124	    }
125	  }
126	
127	  /**
128	   * Handle file modification event
129	   */
130	  private handleFileModify(file: TAbstractFile): void {
131	    if (!this.shouldSyncFile(file)) {
132	      return;
133	    }
134	
135	    this.queueChange(file.path, "content");
136	  }
137	
138	  /**
139	   * Handle file deletion event (placeholder - log only)
140	   */
141	  private handleFileDelete(file: TAbstractFile): void {
142	    if (!(file instanceof TFile) || !file.path.endsWith(".md")) {
143	      return;
144	    }
145	
146	    this.hasPendingOrphanCleanup = true;
147	    this.resetDebounceTimer();
148	  }
149	
150	  /**
151	   * Handle file rename event
152	   */
153	  private handleFileRename(file: TAbstractFile, oldPath: string): void {
154	    if (!this.shouldSyncFile(file)) {
155	      return;
156	    }
157	
158	    this.queueChange(file.path, "title", oldPath);
159	  }
160	
161	  /**
162	   * Handle metadata changes (placeholder for relation metadata)
163	   */
164	  private handleMetadataChange(file: TFile): void {
165	    if (!this.shouldSyncFile(file)) {
166	      return;
167	    }
168	
169	    if (this.pendingCreates.has(file.path)) {
170	      this.queueChange(file.path, "title");
171	      this.queueChange(file.path, "content");
172	      this.pendingCreates.delete(file.path);
173	      return;
174	    }
175	
176	    // Note: pendingCreates helps track files that are created -> added nodeTypeId -> synced to Supabase.
177	    // If a file is created -> added nodeTypeId manually, it won't be detected until the next global sync (onLoad).
178	  }
179	
180	  /**
181	   * Queue a file change for sync
182	   */
183	  private queueChange(
184	    filePath: string,
185	    changeType: ChangeType,
186	    oldPath?: string,
187	  ): void {
188	    const existing = this.changeQueue.get(filePath);
189	    if (existing) {
190	      existing.changeTypes.add(changeType);
191	      if (oldPath && !existing.oldPath) {
192	        existing.oldPath = oldPath;
193	      }
194	    } else {
195	      this.changeQueue.set(filePath, {
196	        filePath,
197	        changeTypes: new Set([changeType]),
198	        oldPath,
199	      });
200	    }
201	
202	    this.resetDebounceTimer();
203	  }
204	
205	  /**
206	   * Reset the debounce timer
207	   */
208	  private resetDebounceTimer(): void {
209	    if (this.debounceTimer) {
210	      clearTimeout(this.debounceTimer);
211	    }
212	
213	    this.debounceTimer = setTimeout(() => {
214	      void this.processQueue();
215	    }, DEBOUNCE_DELAY_MS);
216	  }
217	
218	  /**
219	   * Process the queued changes and sync to Supabase
220	   */
221	  private async processQueue(): Promise<void> {
222	    if (this.isProcessing) {
223	      return;
224	    }
225	
226	    if (this.changeQueue.size === 0 && !this.hasPendingOrphanCleanup) {
227	      return;
228	    }
229	
230	    this.isProcessing = true;
231	
232	    try {
233	      // Process files one by one, removing from queue as we go
234	      const processedFiles: string[] = [];
235	      const failedFiles: string[] = [];
236	
237	      while (this.changeQueue.size > 0) {
238	        // Get the first item from the queue
239	        const firstEntry = this.changeQueue.entries().next().value as
240	          | [string, QueuedChange]
241	          | undefined;
242	
243	        if (!firstEntry) {
244	          break;
245	        }
246	
247	        const [filePath, change] = firstEntry;
248	
249	        try {
250	          const changeTypesByPath = new Map<string, ChangeType[]>();
251	          changeTypesByPath.set(filePath, Array.from(change.changeTypes));
252	
253	          await syncDiscourseNodeChanges(this.plugin, changeTypesByPath);
254	
255	          // Only remove from queue after successful processing
256	          this.changeQueue.delete(filePath);
257	          processedFiles.push(filePath);
258	        } catch (error) {
259	          console.error(
260	            `Error processing file ${filePath}, will retry later:`,
261	            error,
262	          );
263	          // Remove from queue even on failure to prevent infinite retry loops
264	          // Failed files will be re-queued if they change again
265	          this.changeQueue.delete(filePath);
266	          failedFiles.push(filePath);
267	        }
268	      }
269	
270	      if (this.hasPendingOrphanCleanup) {
271	        await cleanupOrphanedNodes(this.plugin);
272	        this.hasPendingOrphanCleanup = false;
273	      }
274	    } catch (error) {
275	      console.error("Error processing sync queue:", error);
276	      // Items that weren't processed remain in the queue for retry
277	    } finally {
278	      this.isProcessing = false;
279	    }
280	  }
281	
282	  /**
283	   * Cleanup event listeners
284	   */
285	  cleanup(): void {
286	    if (this.debounceTimer) {
287	      clearTimeout(this.debounceTimer);
288	      this.debounceTimer = null;
289	    }
290	
291	    this.eventRefs.forEach((ref) => {
292	      this.plugin.app.vault.offref(ref);
293	    });
294	    this.eventRefs = [];
295	
296	    if (this.metadataChangeCallback) {
297	      this.plugin.app.metadataCache.off(
298	        "changed",
299	        this.metadataChangeCallback as (...data: unknown[]) => unknown,
300	      );
301	      this.metadataChangeCallback = null;
302	    }
303	
304	    this.changeQueue.clear();
305	    this.pendingCreates.clear();
306	    this.isProcessing = false;
307	  }
308	}
