67	const getAllNodeInstanceIdsFromSupabase = async (
68	  supabaseClient: DGSupabaseClient,
69	  spaceId: number,
70	): Promise<string[]> => {
71	  try {
72	    const { data, error } = await supabaseClient
73	      .from("my_contents")
74	      .select("source_local_id")
75	      .eq("space_id", spaceId)
76	      .eq("scale", "document")
77	      .not("source_local_id", "is", null);
78	
79	    if (error) {
80	      console.error(
81	        "Failed to get discourse node content from Supabase:",
82	        error,
83	      );
84	      return [];
85	    }
86	
87	    const sourceLocalIds =
88	      data
89	        ?.map((c: { source_local_id: string | null }) => c.source_local_id)
90	        .filter((id: string | null): id is string => !!id) || [];
91	
92	    return [...new Set(sourceLocalIds)];
93	  } catch (error) {
94	    console.error("Error in getAllNodeInstanceIdsFromSupabase:", error);
95	    return [];
96	  }
97	};
