109	const deleteNodesFromSupabase = async (
110	  nodeInstanceIds: string[],
111	  supabaseClient: DGSupabaseClient,
112	  spaceId: number,
113	): Promise<DeleteNodesResult> => {
114	  const result: DeleteNodesResult = {
115	    success: true,
116	    errors: {},
117	  };
118	
119	  try {
120	    if (nodeInstanceIds.length === 0) {
121	      return result;
122	    }
123	
124	    const { error: conceptDeleteError } = await supabaseClient
125	      .from("Concept")
126	      .delete()
127	      .eq("space_id", spaceId)
128	      .in("source_local_id", nodeInstanceIds)
129	      .eq("is_schema", false);
130	
131	    if (conceptDeleteError) {
132	      result.success = false;
133	      result.errors.concept = conceptDeleteError;
134	      console.error(
135	        "Failed to delete concepts from Supabase:",
136	        conceptDeleteError,
137	      );
138	    }
139	
140	    const { error: contentDeleteError } = await supabaseClient
141	      .from("Content")
142	      .delete()
143	      .eq("space_id", spaceId)
144	      .in("source_local_id", nodeInstanceIds);
145	
146	    if (contentDeleteError) {
147	      result.success = false;
148	      result.errors.content = contentDeleteError;
149	      console.error(
150	        "Failed to delete content from Supabase:",
151	        contentDeleteError,
152	      );
153	    }
154	
155	    const { error: documentDeleteError } = await supabaseClient
156	      .from("Document")
157	      .delete()
158	      .eq("space_id", spaceId)
159	      .in("source_local_id", nodeInstanceIds);
160	
161	    if (documentDeleteError) {
162	      result.success = false;
163	      result.errors.document = documentDeleteError;
164	      console.error(
165	        "Failed to delete documents from Supabase:",
166	        documentDeleteError,
167	      );
168	    }
169	  } catch (error) {
170	    result.success = false;
171	    result.errors.unexpected = error;
172	    console.error("Error in deleteNodesFromSupabase:", error);
173	  }
174	
175	  return result;
176	};
