261	const getOrphanedNodeInstanceIds = async ({
262	  plugin,
263	  supabaseClient,
264	  context,
265	}: {
266	  plugin: DiscourseGraphPlugin;
267	  supabaseClient: DGSupabaseClient;
268	  context: SupabaseContext;
269	}): Promise<string[]> => {
270	  const dgNodesInVault = await collectDiscourseNodesFromVault(plugin);
271	  const vaultNodeIds = new Set(
272	    dgNodesInVault.map((node) => node.nodeInstanceId),
273	  );
274	  const supabaseNodeIds = await getAllNodeInstanceIdsFromSupabase(
275	    supabaseClient,
276	    context.spaceId,
277	  );
278	
279	  return supabaseNodeIds.filter((nodeId) => !vaultNodeIds.has(nodeId));
