315	const detectNodeChanges = (
316	  node: DiscourseNodeInVault,
317	  existingTitle: string | undefined,
318	  lastSyncTime: Date,
319	): ChangeType[] => {
320	  const currentFilename = node.file.basename;
321	  const fileModifiedTime = new Date(node.file.stat.mtime);
322	
323	  const isNewFile = existingTitle === undefined;
324	  if (isNewFile) {
325	    return ["title", "content"];
326	  }
327	
328	  const titleChanged = existingTitle !== currentFilename;
329	  const contentChanged = fileModifiedTime > lastSyncTime;
330	
331	  const changeTypes: ChangeType[] = [];
332	  if (titleChanged) {
333	    changeTypes.push("title");
334	  }
335	  if (contentChanged) {
336	    changeTypes.push("content");
337	  }
338	
339	  return changeTypes;
340	};
