342	const buildChangedNodesFromNodes = async ({
343	  nodes,
344	  supabaseClient,
345	  context,
346	  changeTypesByPath,
347	  fullSync = false,
348	  sourceSlotByNodeId,
349	}: BuildChangedNodesOptions): Promise<BuildChangedNodesResult> => {
350	  if (nodes.length === 0) {
351	    return { changedNodes: [] };
352	  }
353	
354	  const nodeInstanceIds = nodes.map((node) => node.nodeInstanceId);
355	  const existingTitleMap = await getExistingTitlesFromDatabase(
356	    supabaseClient,
357	    context.spaceId,
358	    nodeInstanceIds,
359	  );
360	
361	  const lastSyncTime = await getLastContentSyncTime(
362	    supabaseClient,
363	    context.spaceId,
364	  );
365	  const changedNodes: ObsidianDiscourseNodeData[] = [];
366	  let missingConcepts: Set<string> | undefined;
367	  let missingCoreTitleIds: Set<string> | undefined;
368	  let staleSourceSlotIds: Set<string> | undefined;
369	  if (fullSync) {
370	    const existingConceptIds = await getAllPages(
371	      supabaseClient
372	        .from("my_concepts")
373	        .select(`${CORE_TITLE_PROBE_SELECT}, ${SOURCE_SLOT_PROBE_SELECT}`)
374	        .eq("space_id", context.spaceId)
375	        .eq("is_relation", false)
376	        .eq("is_schema", false)
377	        .order("id"),
378	      1000,
379	    );
380	    if (Array.isArray(existingConceptIds)) {
381	      // Here, compensating for concepts that never got upserted
382	      // Probably due to non-atomicity of upsert of concept and content
383	      // TODO try to see if there are other cases
384	      // In particular, using timing when concepts get reordered by dependency
385	      // may be error-prone
386	      // fail silently otherwise, there will be other opportunities
387	      const nodeIds = new Set(nodes.map((n) => n.nodeInstanceId));
388	      const dbConceptIds = new Set(
389	        existingConceptIds
390	          .map((d) => d.source_local_id)
391	          .filter((id) => id !== null),
392	      );
393	      missingConcepts = difference(nodeIds, dbConceptIds);
394	      missingCoreTitleIds =
395	        partitionByCoreTitle(existingConceptIds).missingCoreTitleIds;
396	      if (sourceSlotByNodeId)
397	        staleSourceSlotIds = findStaleSourceSlotNodeIds({
398	          rows: existingConceptIds,
399	          sourceSlotByNodeId,
400	          spaceId: context.spaceId,
401	        });
402	    }
403	  }
404	
405	  for (const node of nodes) {
406	    if (node.frontmatter.importedFromRid) continue;
407	    const existingTitle = existingTitleMap.get(node.nodeInstanceId);
408	    const detectedChangeTypes = detectNodeChanges(
409	      node,
410	      existingTitle,
411	      lastSyncTime,
412	    );
413	    const overrideChangeTypes = changeTypesByPath?.get(node.file.path) ?? [];
414	    const mergedChangeTypes =
415	      overrideChangeTypes.length > 0
416	        ? mergeChangeTypes(overrideChangeTypes, detectedChangeTypes)
417	        : detectedChangeTypes;
418	    const finalChangeTypes = mergedChangeTypes;
419	
420	    if (
421	      finalChangeTypes.length === 0 &&
422	      !missingConcepts?.has(node.nodeInstanceId) &&
423	      !missingCoreTitleIds?.has(node.nodeInstanceId) &&
424	      !staleSourceSlotIds?.has(node.nodeInstanceId)
425	    ) {
426	      continue;
427	    }
428	
429	    changedNodes.push({
430	      file: node.file,
431	      frontmatter: node.frontmatter,
432	      nodeTypeId: node.nodeTypeId,
433	      nodeInstanceId: node.nodeInstanceId,
434	      created: new Date(node.file.stat.ctime).toISOString(),
435	      last_modified: new Date(node.file.stat.mtime).toISOString(),
436	      changeTypes: finalChangeTypes,
437	    });
438	  }
439	
440	  return { changedNodes };
441	};
