464	export const syncAllNodesAndRelations = async (
465	  plugin: DiscourseGraphPlugin,
466	  supabaseContext?: SupabaseContext,
467	  relationsOnly?: boolean,
468	): Promise<void> => {
469	  try {
470	    const context = supabaseContext ?? (await getSupabaseContext(plugin));
471	    if (!context) {
472	      throw new Error("Could not create Supabase context");
473	    }
474	
475	    const supabaseClient = await getLoggedInClient(plugin);
476	    if (!supabaseClient) {
477	      throw new Error("Could not log in to Supabase client");
478	    }
479	
480	    const allNodes = await collectDiscourseNodesFromVault(plugin, true);
481	    const relationInstancesData = await loadRelations(plugin);
482	    const sourceSlotByNodeId = relationsOnly
483	      ? undefined
484	      : indexSourceSlots({
485	          plugin,
486	          nodes: allNodes,
487	          relations: Object.values(relationInstancesData.relations),
488	        });
489	
490	    const { changedNodes: changedNodeInstances } = relationsOnly
491	      ? { changedNodes: [] }
492	      : await buildChangedNodesFromNodes({
493	          nodes: allNodes,
