503	    }
504	
505	    await upsertNodesToSupabaseAsContentWithEmbeddings({
506	      obsidianNodes: changedNodeInstances,
507	      supabaseClient,
508	      context,
509	      accountLocalId,
510	      plugin,
511	    });
512	
513	    await convertDgToSupabaseConcepts({
