517	      plugin,
518	      allNodes,
519	      fullSync: true,
520	      relationInstancesData,
521	      sourceSlotByNodeId,
522	    });
523	
524	    // When synced nodes are already published, ensure non-text assets are in storage.
525	    await syncPublishedNodesAssets(
