535	const convertDgToSupabaseConcepts = async ({
536	  nodesSince,
537	  supabaseClient,
538	  context,
539	  plugin,
540	  allNodes,
541	  fullSync,
542	  relationInstancesData,
543	  sourceSlotByNodeId,
544	}: {
545	  nodesSince: ObsidianDiscourseNodeData[];
546	  supabaseClient: DGSupabaseClient;
547	  context: SupabaseContext;
548	  plugin: DiscourseGraphPlugin;
549	  allNodes?: DiscourseNodeInVault[];
550	  fullSync?: boolean;
551	  relationInstancesData?: RelationsFile;
552	  sourceSlotByNodeId?: Record<string, string>;
553	}): Promise<void> => {
554	  const lastNodeSchemaSync = (
555	    await getLastNodeSchemaSyncTime(supabaseClient, context.spaceId)
556	  ).getTime();
557	  const lastRelationSchemaSync = (
558	    await getLastRelationSchemaSyncTime(supabaseClient, context.spaceId)
