564	  const relationTypes = (plugin.settings.relationTypes ?? []).filter(
565	    isAcceptedSchema,
566	  );
567	  const discourseRelations = (plugin.settings.discourseRelations ?? []).filter(
568	    isAcceptedSchema,
569	  );
570	  allNodes = allNodes ?? (await collectDiscourseNodesFromVault(plugin, true));
571	  const allNodesById = Object.fromEntries(
572	    allNodes.map((n) => [n.nodeInstanceId, n]),
573	  );
574	
575	  const nodeTypesById = Object.fromEntries(
576	    nodeTypes.map((nodeType) => [nodeType.id, nodeType]),
577	  );
578	
579	  const { isEnabled: templatesEnabled, folderPath: templatesFolderPath } =
580	    getTemplatePluginInfo(plugin.app);
581	
582	  let missingTemplateLocalIds = new Set<string | null>();
583	  if (fullSync && templatesEnabled && templatesFolderPath) {
584	    const absentTemplates = await supabaseClient
585	      .from("my_concepts")
586	      .select("source_local_id,literal_content")
587	      .eq("is_schema", true)
588	      .eq("is_relation", false)
589	      .eq("space_id", context.spaceId)
590	      .is("literal_content->>template_content", null);
591	    // could not filter on only absent keys, this includes nulls
592	
593	    if (absentTemplates.data && absentTemplates.data.length > 0) {
594	      missingTemplateLocalIds = new Set(
595	        absentTemplates.data
596	          .filter(
597	            (x) =>
598	              (x.literal_content as Record<string, Json>).template_content !==
599	              null,
600	          )
601	          .map((x) => x["source_local_id"]),
602	      );
603	    }
604	  }
605	
606	  const nodesTypesToLocalConcepts = await Promise.all(
607	    nodeTypes
608	      .filter(
609	        (nodeType) =>
610	          nodeType.modified > lastNodeSchemaSync ||
611	          missingTemplateLocalIds.has(nodeType.id),
612	      )
613	      .map(async (nodeType) => {
614	        let templateContent: string | undefined;
615	        if (nodeType.template && templatesEnabled && templatesFolderPath) {
616	          const templateFilePath = `${templatesFolderPath}/${nodeType.template}.md`;
617	          const templateFile =
618	            plugin.app.vault.getAbstractFileByPath(templateFilePath);
619	          if (templateFile instanceof TFile) {
620	            templateContent = await plugin.app.vault.read(templateFile);
621	          }
622	        }
623	        return discourseNodeSchemaToLocalConcept({
624	          context,
625	          node: nodeType,
626	          templateContent,
627	        });
628	      }),
629	  );
630	
631	  const relationTypesById = Object.fromEntries(
632	    relationTypes.map((relationType) => [relationType.id, relationType]),
633	  );
634	
635	  const relationTypesToLocalConcepts = relationTypes
636	    .filter((relationType) => relationType.modified > lastRelationSchemaSync)
637	    .map((relationType) =>
638	      discourseRelationTypeToLocalConcept(context, relationType),
639	    );
640	
641	  const discourseRelationTriplesToLocalConcepts = discourseRelations
642	    .filter(
643	      (relationTriple) =>
644	        relationTriple.modified > lastRelationSchemaSync ||
645	        // resync if type was changed, to update labels in triple
646	        (relationTypesById[relationTriple.relationshipTypeId]?.modified ?? 0) >
647	          lastRelationSchemaSync ||
648	        // resync if source or destination node type was changed, to update names in triple
649	        (nodeTypesById[relationTriple.sourceId]?.modified ?? 0) >
650	          lastNodeSchemaSync ||
651	        (nodeTypesById[relationTriple.destinationId]?.modified ?? 0) >
652	          lastNodeSchemaSync,
653	    )
654	    .map((relation) =>
655	      discourseRelationTripleSchemaToLocalConcept({
656	        context,
657	        relation,
658	        nodeTypesById,
659	        relationTypesById,
660	      }),
661	    )
662	    .filter((n) => !!n);
663	
664	  relationInstancesData =
665	    relationInstancesData ?? (await loadRelations(plugin));
666	  const relationInstances = Object.values(relationInstancesData.relations);
667	  sourceSlotByNodeId =
668	    sourceSlotByNodeId ??
669	    indexSourceSlots({ plugin, nodes: allNodes, relations: relationInstances });
670	  sourceSlotByNodeId = await filterAvailableSourceSlotValues({
671	    sourceSlotByNodeId: Object.fromEntries(
672	      nodesSince.flatMap(({ nodeInstanceId }) => {
673	        const sourceId = sourceSlotByNodeId?.[nodeInstanceId];
674	        return sourceId ? [[nodeInstanceId, sourceId]] : [];
675	      }),
676	    ),
677	    client: supabaseClient,
678	    spaceId: context.spaceId,
679	    pendingNodeIds: new Set(nodesSince.map((node) => node.nodeInstanceId)),
680	  });
681	  const nodeInstanceToLocalConcepts = nodesSince.map((node) => {
