697	        (relationInstanceData.lastModified || relationInstanceData.created) >
698	          lastRelationsSync,
699	    )
700	    .map((relationInstanceData) =>
701	      relationInstanceToLocalConcept({
702	        context,
703	        relationTypesById,
704	        allNodesById,
705	        relationInstanceData,
706	      }),
707	    )
708	    .filter((n) => !!n);
709	
710	  const conceptsToUpsert: LocalConceptDataInput[] = [
711	    ...nodesTypesToLocalConcepts,
712	    ...relationTypesToLocalConcepts,
713	    ...discourseRelationTriplesToLocalConcepts,
714	    ...nodeInstanceToLocalConcepts,
715	    ...relationInstanceToLocalConcepts,
716	  ];
717	
718	  if (conceptsToUpsert.length > 0) {
719	    const { ordered } = orderConceptsByDependency(conceptsToUpsert);
720	
721	    const { error } = await supabaseClient.rpc("upsert_concepts", {
722	      data: ordered as Json,
723	      v_space_id: context.spaceId,
724	    });
725	
726	    if (error) {
