728	        error instanceof Error
729	          ? error.message
730	          : typeof error === "string"
731	            ? error
732	            : JSON.stringify(error, null, 2);
733	      throw new Error(`upsert_concepts failed: ${errorMessage}`);
734	    }
735	  }
736	  if (fullSync === true) {
737	    // occasional extra work: Make sure relations that should be published are.
738	    await ensurePublishedRelationsAccuracy({
739	      client: supabaseClient,
740	      context,
741	      plugin,
742	      allNodesById,
743	      relationInstancesData,
744	    });
745	  }
