748	/**
749	 * An embedded asset, kept as both halves of what a `FileReference` records: the link the
750	 * note wrote, and the file that link resolves to.
751	 *
752	 * The two differ under Obsidian's default shortest-path setting, where a note embeds
753	 * `diagram.png` while the file lives at `attachments/diagram.png`. `filepath` has to be
754	 * what the content says, so a destination can match it without knowing Obsidian's link
755	 * conventions; `source_path` has to be the vault path, so the folder layout survives an
756	 * import.
757	 */
758	export type EmbeddedAttachment = { link: string; file: TFile };
759	
760	/** Resolves a note's embeds against the vault, dropping links that resolve to nothing. */
761	export const findEmbeddedAttachments = (
762	  plugin: DiscourseGraphPlugin,
763	  file: TFile,
764	): EmbeddedAttachment[] => {
765	  const embeds = plugin.app.metadataCache.getFileCache(file)?.embeds ?? [];
766	  const byLink = new Map<string, EmbeddedAttachment>();
767	  for (const { link } of embeds) {
768	    if (byLink.has(link)) continue;
769	    const resolved = plugin.app.metadataCache.getFirstLinkpathDest(
770	      link,
771	      file.path,
772	    );
773	    if (resolved) byLink.set(link, { link, file: resolved });
774	  }
775	  return [...byLink.values()];
776	};
