778	export const syncPublishedNodeAssets = async ({
779	  plugin,
780	  client,
781	  nodeId,
782	  spaceId,
783	  file,
784	  attachments,
785	}: {
786	  plugin: DiscourseGraphPlugin;
787	  client: DGSupabaseClient;
788	  nodeId: string;
789	  spaceId: number;
790	  file: TFile;
791	  attachments?: EmbeddedAttachment[];
792	}): Promise<void> => {
793	  if (attachments === undefined)
794	    attachments = findEmbeddedAttachments(plugin, file);
795	  // Always sync non-text assets when node is published to this group
796	  const existingFiles: string[] = [];
797	  const existingReferencesReq = await client
798	    .from("my_file_references")
799	    .select("*")
800	    .eq("space_id", spaceId)
801	    .eq("source_local_id", nodeId);
802	  if (existingReferencesReq.error) {
803	    console.error(existingReferencesReq.error);
804	    return;
805	  }
806	  const existingReferencesByPath = Object.fromEntries(
807	    existingReferencesReq.data.map((ref) => [ref.filepath, ref]),
808	  ) as Record<string, (typeof existingReferencesReq.data)[0]>;
809	
810	  for (const { link, file: attachment } of attachments) {
811	    // The extension comes from the resolved file: a link may be written without one.
812	    const mimetype = mime.lookup(attachment.path) || "application/octet-stream";
813	    if (mimetype.startsWith("text/")) continue;
814	    // Do not use standard upload for large files
815	    if (isAssetTooLarge(attachment.stat.size)) {
816	      new Notice(
817	        `Asset file ${attachment.path} is larger than 6Mb and will not be uploaded`,
818	      );
819	      continue;
820	    }
821	    // Rows are keyed on the link, so respelling a link replaces the row rather than
822	    // accumulating one per spelling. Rows predating the split hold a resolved path here,
823	    // match no link, and the cleanup below drops them: re-publishing corrects them.
824	    existingFiles.push(link);
825	    const existingRef = existingReferencesByPath[link];
826	    // Rewrite the row when its bytes are stale, and also when where it says the file
827	    // lives is stale. The second case is not about content: a row predating the split
828	    // carries no `source_path`, and one whose link happens to equal the old stored path
829	    // would never be corrected, since the asset itself never changed. It also covers an
830	    // asset moved in the vault while its link stayed the same. Self-limiting: after one
831	    // sync the recorded path matches and this stops firing.
832	    if (
833	      !existingRef ||
834	      existingRef.source_path !== attachment.path ||
835	      new Date(existingRef.last_modified + "Z").valueOf() <
836	        attachment.stat.mtime
837	    ) {
838	      const content = await plugin.app.vault.readBinary(attachment);
839	      await addFile({
840	        client,
841	        spaceId,
842	        sourceLocalId: nodeId,
843	        fname: link,
844	        sourcePath: attachment.path,
845	        mimetype,
846	        created: new Date(attachment.stat.ctime),
847	        lastModified: new Date(attachment.stat.mtime),
848	        content,
849	      });
850	    }
851	  }
852	  let cleanupCommand = client
853	    .from("FileReference")
854	    .delete()
855	    .eq("space_id", spaceId)
856	    .eq("source_local_id", nodeId);
857	  if (existingFiles.length)
858	    cleanupCommand = cleanupCommand.notIn("filepath", [
859	      ...new Set(existingFiles),
860	    ]);
861	  const cleanupResult = await cleanupCommand;
862	  // do not fail on cleanup
863	  if (cleanupResult.error) console.error(cleanupResult.error);
864	};
