866	/**
867	 * For nodes that are already published, ensure non-text assets are pushed to
868	 * storage. Called after content sync so new embeds (e.g. images) get uploaded.
869	 */
870	const syncPublishedNodesAssets = async (
871	  plugin: DiscourseGraphPlugin,
872	  nodes: ObsidianDiscourseNodeData[],
873	): Promise<void> => {
874	  const context = await getSupabaseContext(plugin);
875	  if (!context) throw new Error("Cannot get context");
876	  const spaceId = context.spaceId;
877	  const client = await getLoggedInClient(plugin);
878	  if (!client) throw new Error("Cannot get client");
879	  const published = nodes.filter(
880	    (n) =>
881	      ((n.frontmatter.publishedToGroups as string[] | undefined)?.length ?? 0) >
882	      0,
883	  );
884	  for (const node of published) {
885	    try {
886	      const nodeId = node.frontmatter.nodeInstanceId as string | undefined;
887	      if (!nodeId) throw new Error("Please sync the node first");
888	      await syncPublishedNodeAssets({
889	        plugin,
890	        client,
891	        nodeId,
892	        spaceId,
893	        file: node.file,
894	      });
895	    } catch (error) {
896	      console.error(
897	        `Failed to sync published node assets for ${node.file.path}:`,
898	        error,
899	      );
900	    }
901	  }
902	};
