904	/**
905	 * Shared function to sync changed nodes to Supabase
906	 * Handles content/embedding upsert and concept upsert
907	 */
908	const syncChangedNodesToSupabase = async ({
909	  changedNodes,
910	  plugin,
911	  supabaseClient,
912	  context,
913	  accountLocalId,
914	}: {
915	  changedNodes: ObsidianDiscourseNodeData[];
916	  plugin: DiscourseGraphPlugin;
917	  supabaseClient: DGSupabaseClient;
918	  context: SupabaseContext;
919	  accountLocalId: string;
920	}): Promise<void> => {
921	  if (changedNodes.length > 0) {
922	    await upsertNodesToSupabaseAsContentWithEmbeddings({
923	      obsidianNodes: changedNodes,
924	      supabaseClient,
925	      context,
926	      accountLocalId,
927	      plugin,
928	    });
929	  }
930	
931	  // Only upsert concepts for nodes with title changes or new files
932	  // (concepts store the title, so content-only changes don't affect them)
933	  const nodesNeedingConceptUpsert = changedNodes.filter((node) =>
934	    node.changeTypes.includes("title"),
935	  );
936	
937	  await convertDgToSupabaseConcepts({
938	    nodesSince: nodesNeedingConceptUpsert,
939	    supabaseClient,
940	    context,
941	    plugin,
942	  });
