944	  // When file changes affect an already-published node, ensure new non-text
945	  // assets (e.g. images) are pushed to storage.
946	  try {
947	    await syncPublishedNodesAssets(plugin, changedNodes);
948	  } catch (error) {
949	    console.error(`Failed to sync published node assets`, error);
950	    new Notice(`Failed to sync published node assets.`);
