957	const collectDiscourseNodesFromPaths = async (
958	  plugin: DiscourseGraphPlugin,
959	  filePaths: string[],
960	): Promise<DiscourseNodeInVault[]> => {
961	  const dgNodes: DiscourseNodeInVault[] = [];
962	
963	  for (const filePath of filePaths) {
964	    const file = plugin.app.vault.getAbstractFileByPath(filePath);
965	    if (!(file instanceof TFile)) {
966	      continue;
967	    }
968	
969	    // Only process markdown files
970	    if (!file.path.endsWith(".md")) {
971	      continue;
972	    }
973	
974	    const cache = plugin.app.metadataCache.getFileCache(file);
975	    const frontmatter = cache?.frontmatter;
976	
977	    // Not a discourse node
978	    if (!frontmatter?.nodeTypeId) {
979	      continue;
980	    }
981	
982	    if (frontmatter.importedFromRid) {
983	      continue;
984	    }
985	
986	    const nodeTypeId = frontmatter.nodeTypeId as string;
987	    if (!nodeTypeId) {
988	      continue;
989	    }
990	
991	    const nodeInstanceId = await ensureNodeInstanceId(
992	      plugin,
993	      file,
994	      frontmatter as Record<string, unknown>,
995	    );
996	
997	    dgNodes.push({
998	      file,
999	      frontmatter: frontmatter as Record<string, unknown>,
1000	      nodeTypeId,
1001	      nodeInstanceId,
1002	    });
1003	  }
1004	
1005	  return dgNodes;
1006	};
