105	export const fetchEmbeddingsForNodes = async (
106	  nodes: LocalContentDataInput[],
107	): Promise<LocalContentDataInput[]> => {
108	  const allEmbeddings: number[][] = [];
109	  const allNodesTexts = nodes.map((node) => node.text || "");
110	
111	  for (let i = 0; i < allNodesTexts.length; i += EMBEDDING_BATCH_SIZE) {
112	    const batch = allNodesTexts.slice(i, i + EMBEDDING_BATCH_SIZE);
113	    const response = await fetch(nextApiRoot() + "/embeddings/openai/small", {
114	      method: "POST",
115	      headers: { "Content-Type": "application/json" },
116	      body: JSON.stringify({ input: batch }),
117	    });
118	
119	    if (!response.ok) {
120	      let errorData;
121	      try {
122	        errorData = (await response.json()) as { error: string };
123	      } catch (e) {
124	        errorData = {
125	          error: `Server responded with ${response.status}: ${await response.text()}`,
126	        };
127	      }
128	      throw new Error(
129	        `API Error (${response.status}) processing batch ${
130	          i / EMBEDDING_BATCH_SIZE + 1
131	        }: ${errorData.error || "Failed to fetch embeddings"}`,
132	      );
133	    }
134	
135	    const data = (await response.json()) as EmbeddingApiResponse;
136	    if (!data || !Array.isArray(data.data)) {
137	      throw new Error(
138	        `Invalid API response format for batch ${
139	          i / EMBEDDING_BATCH_SIZE + 1
140	        }. Expected 'data' array.`,
141	      );
142	    }
143	    const batchEmbeddings = data.data.map((item) => item.embedding);
144	    allEmbeddings.push(...batchEmbeddings);
145	  }
146	
147	  if (nodes.length !== allEmbeddings.length) {
148	    throw new Error(
149	      `Mismatch between nodes (${nodes.length}) and embeddings (${allEmbeddings.length})`,
150	    );
151	  }
152	
153	  return nodes.map((node, i) => ({
154	    ...node,
155	    embedding_inline: {
156	      model: EMBEDDING_MODEL,
157	      vector: allEmbeddings[i] as number[],
158	    },
159	  }));
160	};
