162	const uploadBatches = async (
163	  batches: LocalContentDataInput[][],
164	  supabaseClient: DGSupabaseClient,
165	  context: SupabaseContext,
166	): Promise<void> => {
167	  const { spaceId, userId } = context;
168	  for (let idx = 0; idx < batches.length; idx++) {
169	    const batch = batches[idx];
170	    const { error } = await supabaseClient.rpc("upsert_content", {
171	      data: batch as unknown as Json,
172	      v_space_id: spaceId,
173	      v_creator_id: userId,
174	      content_as_document: true,
175	    });
176	
177	    if (error) {
178	      console.error(`upsert_content failed for batch ${idx + 1}:`, error);
179	      throw error;
180	    }
181	  }
182	};
