35	const publishSchema = async ({
36	  client,
37	  spaceId,
38	  nodeTypeId,
39	  groupId,
40	}: {
41	  client: DGSupabaseClient;
42	  spaceId: number;
43	  nodeTypeId: string;
44	  groupId: string;
45	}): Promise<void> => {
46	  // Check if schema exists
47	  const schemaResponse = await client
48	    .from("Concept")
49	    .select("source_local_id")
50	    .eq("space_id", spaceId)
51	    .eq("is_schema", true)
52	    .eq("source_local_id", nodeTypeId)
53	    .maybeSingle();
54	
55	  if (schemaResponse.error) {
56	    console.error("Error checking schema existence:", schemaResponse.error);
57	    return; // Don't fail node publishing if schema check fails
58	  }
59	
60	  if (!schemaResponse.data) {
61	    return; // Schema doesn't exist, skip publishing
62	  }
63	
64	  // Publish schema to group via ResourceAccess
65	  const publishResponse = await client.from("ResourceAccess").upsert(
66	    {
67	      account_uid: groupId,
68	      source_local_id: nodeTypeId,
69	      space_id: spaceId,
70	    },
71	    { ignoreDuplicates: true },
72	  );
73	
74	  if (publishResponse.error && publishResponse.error.code !== "23505") {
75	    // 23505 is duplicate key, which counts as a success.
76	    console.error("Error publishing schema:", publishResponse.error);
77	    // Don't throw - schema publishing failure shouldn't block node publishing
78	  }
