81	export const publishNewRelation = async (
82	  plugin: DiscourseGraphPlugin,
83	  relation: RelationInstance,
84	): Promise<boolean> => {
85	  const client = await getLoggedInClient(plugin);
86	  if (!client) throw new Error("Cannot get client");
87	  const context = await getSupabaseContext(plugin);
88	  if (!context) throw new Error("Cannot get context");
89	  const sourceFile = getFileForNodeInstanceId(plugin, relation.source);
90	  const destinationFile = getFileForNodeInstanceId(
91	    plugin,
92	    relation.destination,
93	  );
94	  if (!sourceFile || !destinationFile) return false;
95	  const sourceFm =
96	    plugin.app.metadataCache.getFileCache(sourceFile)?.frontmatter;
97	  const destinationFm =
98	    plugin.app.metadataCache.getFileCache(destinationFile)?.frontmatter;
99	  if (!sourceFm || !destinationFm) return false;
100	
101	  const sourceGroups = sourceFm.publishedToGroups as string[] | undefined;
102	  const destinationGroups = destinationFm.publishedToGroups as
103	    | string[]
104	    | undefined;
105	  if (!Array.isArray(sourceGroups) || !Array.isArray(destinationGroups))
106	    return false;
107	  const relationTriples = plugin.settings.discourseRelations ?? [];
108	  const triple = relationTriples.find(
109	    (triple) =>
110	      triple.relationshipTypeId === relation.type &&
111	      triple.sourceId === sourceFm.nodeTypeId &&
112	      triple.destinationId === destinationFm.nodeTypeId,
113	  );
114	  if (!triple) return false;
115	  if (isProvisionalSchema(triple)) return false;
116	  const relationType = plugin.settings.relationTypes.find(
117	    (rt) => rt.id === relation.type,
118	  );
119	  if (relationType && isProvisionalSchema(relationType)) return false;
120	  if (relation.tentative === false) return false;
121	  const resourceIds = [relation.id, relation.type, triple.id];
122	  const myGroups = await getAvailableGroupIds(client);
123	  const targetGroups = intersection(
124	    new Set(myGroups),
125	    intersection(
126	      new Set<string>(sourceGroups),
127	      new Set<string>(destinationGroups),
128	    ),
129	  );
130	  if (!targetGroups.size) return false;
131	  // in that case, sync all relations (only) before publishing
132	  await syncAllNodesAndRelations(plugin, context, true);
133	  const entries = [];
134	  for (const group of targetGroups) {
135	    for (const id of resourceIds) {
136	      entries.push({
137	        account_uid: group,
138	        source_local_id: id,
139	        space_id: context.spaceId,
140	      });
141	    }
142	  }
143	  const publishResponse = await client
144	    .from("ResourceAccess")
145	    .upsert(entries, { ignoreDuplicates: true });
146	  if (publishResponse.error && publishResponse.error.code !== "23505")
147	    throw publishResponse.error;
148	  relation.publishedToGroupId = [
149	    ...new Set([
150	      ...(relation.publishedToGroupId || []),
151	      ...targetGroups.values(),
152	    ]).values(),
153	  ];
154	  return true;
155	};
