157	export const publishNodeRelations = async ({
158	  plugin,
159	  client,
160	  nodeId,
161	  myGroup,
162	  spaceId,
163	}: {
164	  plugin: DiscourseGraphPlugin;
165	  client: DGSupabaseClient;
166	  nodeId: string;
167	  myGroup: string;
168	  spaceId: number;
169	}): Promise<void> => {
170	  const relations = await getRelationsForNodeInstanceId(plugin, nodeId);
171	  const resourceIds: Set<string> = new Set();
172	  const relationTriples = plugin.settings.discourseRelations ?? [];
173	  const relevantNodeIds: Set<string> = new Set();
174	  relations.map((relation) => {
175	    relevantNodeIds.add(relation.source);
176	    relevantNodeIds.add(relation.destination);
177	  });
178	  const relevantNodeFiles = getFileForNodeInstanceIds(plugin, relevantNodeIds);
179	  const relevantNodeTypeById: Record<string, string | undefined> = {};
180	  Object.entries(relevantNodeFiles).map(([id, file]: [string, TFile]) => {
181	    const fm = plugin.app.metadataCache.getFileCache(file)?.frontmatter;
182	    if (fm === undefined) return;
183	    if (fm.nodeInstanceId !== nodeId) {
184	      // check if published to same group.
185	      // Note: current node's pub status not in cache yet!
186	      if (!Array.isArray(fm.publishedToGroups)) return;
187	      const publishedToGroups: string[] =
188	        (fm.publishedToGroups as string[]) || [];
189	      if (!publishedToGroups.includes(myGroup)) return;
190	    }
191	    relevantNodeTypeById[id] = fm.nodeTypeId as string;
192	  });
193	  relations.map((relation) => {
194	    if ((relation.publishedToGroupId ?? []).includes(myGroup)) return;
195	    const triple = relationTriples.find(
196	      (triple) =>
197	        triple.relationshipTypeId === relation.type &&
198	        triple.sourceId === relevantNodeTypeById[relation.source] &&
199	        triple.destinationId === relevantNodeTypeById[relation.destination],
200	    );
201	    if (triple) {
202	      resourceIds.add(relation.id);
203	      resourceIds.add(relation.type);
204	      resourceIds.add(triple.id);
205	    }
206	  });
207	  if (resourceIds.size === 0) return;
208	  const publishResponse = await client.from("ResourceAccess").upsert(
209	    [...resourceIds.values()].map((sourceLocalId: string) => ({
210	      account_uid: myGroup,
211	      source_local_id: sourceLocalId,
212	      space_id: spaceId,
213	    })),
214	    { ignoreDuplicates: true },
215	  );
216	  if (publishResponse.error && publishResponse.error.code !== "23505")
217	    throw publishResponse.error;
218	  const relData = await loadRelations(plugin);
219	  let dataChanged = false;
220	  relations
221	    .filter((rel) => resourceIds.has(rel.id))
222	    .map((rel) => {
223	      const savedRel = relData.relations[rel.id];
224	      if (!savedRel) return;
225	      const publishedTo = savedRel.publishedToGroupId;
226	      if (!publishedTo) {
227	        savedRel.publishedToGroupId = [myGroup];
228	        dataChanged = true;
229	      } else if (!publishedTo.includes(myGroup)) {
230	        publishedTo.push(myGroup);
231	        dataChanged = true;
232	      }
