265	export const ensurePublishedRelationsAccuracy = async ({
266	  client,
267	  context,
268	  plugin,
269	  allNodesById,
270	  relationInstancesData,
271	}: {
272	  client: DGSupabaseClient;
273	  context: SupabaseContext;
274	  plugin: DiscourseGraphPlugin;
275	  allNodesById: Record<string, DiscourseNodeInVault>;
276	  relationInstancesData: RelationsFile;
277	}): Promise<void> => {
278	  const myGroups = await getAvailableGroupIds(client);
279	  const relationInstances = Object.values(relationInstancesData.relations);
280	  const syncedRelationIdsResult = await client
281	    .from("Concept")
282	    .select("source_local_id")
283	    .eq("space_id", context.spaceId)
284	    .eq("is_schema", false)
285	    .eq("is_relation", true);
286	  if (syncedRelationIdsResult.error) {
287	    console.error(
288	      "Could not get synced relation ids",
289	      syncedRelationIdsResult.error,
290	    );
291	    return;
292	  }
293	  const syncedRelationIds = new Set(
294	    (syncedRelationIdsResult.data || []).map((x) => x.source_local_id!),
295	  );
296	  // Also a good time to look at orphan relations
297	  const existingRelationIds = new Set(relationInstances.map((r) => r.id));
298	  const orphanRelationIds = difference(syncedRelationIds, existingRelationIds);
299	  if (orphanRelationIds.size) {
300	    const r = await client
301	      .from("Concept")
302	      .delete()
303	      .eq("space_id", context.spaceId)
304	      .in("source_local_id", [...orphanRelationIds]);
305	    if (!r.error) {
306	      for (const id of orphanRelationIds) {
307	        syncedRelationIds.delete(id);
308	      }
309	    }
310	  }
311	  let changed = false;
312	  const missingPublishRecords: TablesInsert<"ResourceAccess">[] = [];
313	  for (const group of myGroups) {
314	    const publishableRelations = relationInstances.filter(
315	      (r) =>
316	        !r.importedFromRid &&
317	        syncedRelationIds.has(r.id) &&
318	        (
319	          (allNodesById[r.source]?.frontmatter?.publishedToGroups as
320	            | string[]
321	            | undefined) || []
322	        ).indexOf(group) >= 0 &&
323	        (
324	          (allNodesById[r.destination]?.frontmatter?.publishedToGroups as
325	            | string[]
326	            | undefined) || []
327	        ).indexOf(group) >= 0,
328	    );
329	    const publishableRelationIds = new Set(
330	      publishableRelations.map((x) => x.id),
331	    );
332	    const publishedIds = await client
333	      .from("ResourceAccess")
334	      .select("source_local_id")
335	      .eq("account_uid", group)
336	      .eq("space_id", context.spaceId);
337	    if (publishedIds.error) {
338	      console.error("Could not get synced relation ids", publishedIds.error);
339	      continue;
340	    }
341	    const publishedRelationIds = intersection(
342	      syncedRelationIds,
343	      new Set((publishedIds.data || []).map((x) => x.source_local_id)),
344	    );
345	    const missingPublishableIds = difference(
346	      publishableRelationIds,
347	      publishedRelationIds,
348	    );
349	    if (missingPublishableIds.size > 0) {
350	      missingPublishRecords.push(
351	        ...[...missingPublishableIds].map((source_local_id) => ({
352	          source_local_id,
353	          space_id: context.spaceId,
354	          account_uid: group,
355	        })),
356	      );
357	    }
358	    const extraPublishableIds = difference(
359	      publishedRelationIds,
360	      publishableRelationIds,
361	    );
362	    if (extraPublishableIds.size > 0) {
363	      const r = await client
364	        .from("ResourceAccess")
365	        .delete()
366	        .eq("account_uid", group)
367	        .eq("space_id", context.spaceId)
368	        .in("source_local_id", [...extraPublishableIds]);
369	      if (r.error) console.error(r.error);
370	      else {
371	        for (const id of extraPublishableIds) {
372	          const rel = relationInstancesData.relations[id];
373	          const pos = (rel?.publishedToGroupId || []).indexOf(group);
374	          if (pos >= 0) {
375	            rel!.publishedToGroupId!.splice(pos, 1);
376	            changed = true;
377	          }
378	        }
379	      }
380	    }
381	  }
382	  if (missingPublishRecords.length > 0) {
383	    const r = await client.from("ResourceAccess").upsert(missingPublishRecords);
384	    if (r.error) console.error(r.error);
385	    else {
386	      for (const record of missingPublishRecords) {
387	        const rel = relationInstancesData.relations[record.source_local_id];
388	        const group = record.account_uid;
389	        const pos = (rel?.publishedToGroupId || []).indexOf(group);
390	        if (rel && pos < 0) {
391	          if (rel.publishedToGroupId === undefined) rel.publishedToGroupId = [];
392	          rel.publishedToGroupId.push(group);
393	          changed = true;
394	        }
395	      }
396	    }
397	  }
398	  if (changed) {
399	    await saveRelations(plugin, relationInstancesData);
400	  }
401	};
