403	export const publishNodeToGroup = async ({
404	  plugin,
405	  file,
406	  frontmatter,
407	  myGroup,
408	  skipFrontmatterUpdate = false,
409	}: {
410	  plugin: DiscourseGraphPlugin;
411	  file: TFile;
412	  frontmatter: FrontMatterCache;
413	  myGroup: string;
414	  skipFrontmatterUpdate?: boolean;
415	}): Promise<void> => {
416	  const nodeId = frontmatter.nodeInstanceId as string | undefined;
417	  if (!nodeId) throw new Error("Please sync the node first");
418	  const context = await getSupabaseContext(plugin);
419	  if (!context) throw new Error("Cannot get context");
420	  const spaceId = context.spaceId;
421	  const client = await getLoggedInClient(plugin);
422	  if (!client) throw new Error("Cannot get client");
423	  const existingPublish =
424	    (frontmatter.publishedToGroups as undefined | string[]) || [];
425	
426	  const idResponse = await client
427	    .from("my_contents")
428	    .select("last_modified")
429	    .eq("source_local_id", nodeId)
430	    .eq("space_id", spaceId)
431	    .eq("variant", "full")
432	    .maybeSingle();
433	  if (idResponse.error || !idResponse.data) {
434	    throw idResponse.error || new Error("no data while fetching node");
435	  }
436	  const lastModifiedDb = new Date(
437	    idResponse.data.last_modified + "Z",
438	  ).getTime();
439	  try {
440	    await publishNodeRelations({ plugin, client, nodeId, myGroup, spaceId });
441	  } catch (error) {
442	    // do not fail to publish node for that reason
443	    console.error("Could not publish relations", error);
444	  }
445	  const attachments = findEmbeddedAttachments(plugin, file);
446	  const lastModified = Math.max(
447	    file.stat.mtime,
448	    ...attachments.map((a) => a.file.stat.mtime),
449	  );
450	
451	  const skipPublishAccess =
452	    existingPublish.includes(myGroup) && lastModified <= lastModifiedDb;
453	
454	  if (!skipPublishAccess) {
455	    const publishSpaceResponse = await client.from("SpaceAccess").upsert(
456	      {
457	        account_uid: myGroup,
458	        space_id: spaceId,
459	        permissions: "partial",
460	      },
461	      { ignoreDuplicates: true },
462	    );
463	    if (
464	      publishSpaceResponse.error &&
465	      publishSpaceResponse.error.code !== "23505"
466	    )
467	      throw publishSpaceResponse.error;
468	
469	    const publishResponse = await client.from("ResourceAccess").upsert(
470	      {
471	        account_uid: myGroup,
472	        source_local_id: nodeId,
473	        space_id: spaceId,
474	      },
475	      { ignoreDuplicates: true },
476	    );
477	    if (publishResponse.error && publishResponse.error.code !== "23505")
478	      throw publishResponse.error;
479	
480	    const nodeTypeId = frontmatter.nodeTypeId as string | undefined;
481	    if (nodeTypeId) {
482	      await publishSchema({
483	        client,
484	        spaceId,
485	        nodeTypeId,
486	        groupId: myGroup,
487	      });
488	    }
489	  }
490	  await syncPublishedNodeAssets({
491	    plugin,
492	    client,
493	    nodeId,
494	    spaceId,
495	    file,
496	    attachments,
497	  });
498	  if (!skipFrontmatterUpdate && !existingPublish.includes(myGroup)) {
499	    await plugin.app.fileManager.processFrontMatter(
500	      file,
501	      (fm: Record<string, unknown>) => {
502	        const current = getPublishedToGroups(fm);
503	        if (!current.includes(myGroup)) {
504	          fm.publishedToGroups = [...current, myGroup];
505	        }
506	      },
507	    );
508	  }
509	};
